// ---------- SIM CONFIG ----------
const SIM = {
  // Character + assets
  characterHash: '1567edfe9a2e96c5',
  totalPosesRequired: 2,                  // set 12 for full run
  assetsRoot: 'book-mvp-simple-adventure',
  orderAssetsPrefix: 'order-generated-assets',
  baseCharacterFilename: 'base-character.png',
  publicR2Url: 'https://pub-92cec53654f84771956bc84dfea65baa.r2.dev',
  posesPublicBase: 'https://pub-92cec53654f84771956bc84dfea65baa.r2.dev/little-hero-assets/book-mvp-simple-adventure/characters/poses/',
  get characterPath() { return `characters/${this.characterHash}`; },

  // Order/character knobs
  customerEmail: 'jeff@example.com',

  // These match what your prod prompt builder reads
  characterSpecs: {
