return [{ json: order }];

// Expand to N Poses — v2.4 (JSON-only fan-out; staticData-aware; deterministic)
// Mode: Run Once for All Items (ALL)
// Uses the first incoming item as the source and emits N JSON copies with pose fields.

const item = $input.first() || { json: {}, binary: {} };
const j = item.json || {};

function good(x){
  return typeof x === 'string'
    ? x.trim() !== '' && x.trim().toLowerCase() !== 'unknown-order'
    : x !== undefined && x !== null;
}
function pickNE(){ for (const a of arguments){ if (good(a)) return a; } return null; }

$execution.customData = $execution.customData || {};
const execCtx = $execution.customData.orderContext || {};
const inCtx   = j.orderContext || {};
const sd      = $getWorkflowStaticData('global');

// Resolve amazonOrderId with robust precedence:
// item → item.orderContext → $execution.customData → staticData.lastAmazonOrderId → staticData.lastOrderContext → global (last resort)
const incoming  = j.amazonOrderId || null;
const ctxId     = inCtx.amazonOrderId || null;
const execId    = execCtx.amazonOrderId || null;
const staticId  = sd?.lastAmazonOrderId || null;
const staticCtx = sd?.lastOrderContext?.amazonOrderId || null;
// NOTE: `global` is not reliably shared across nodes; leave as lowest-priority fallback.
const globalId  = global?.currentAmazonOrderId || null;

const amazonOrderId = pickNE(
  incoming,
  ctxId,
  execId,
  staticId,
  staticCtx,
  globalId
) || 'unknown-order';

// Merge a durable order context with defaults for assets/public URL
const mergedCtx = {
  ...execCtx,
  ...inCtx,
  amazonOrderId,
  publicR2Url: inCtx.publicR2Url || execCtx.publicR2Url || sd?.lastOrderContext?.publicR2Url || 'https://pub-92cec53654f84771956bc84dfea65baa.r2.dev',
  assetsRoot : inCtx.assetsRoot  || execCtx.assetsRoot  || sd?.lastOrderContext?.assetsRoot  || 'book-mvp-simple-adventure/order-generated-assets',
};

// Persist for downstream reliability
$execution.customData.orderContext = mergedCtx;
if (good(amazonOrderId)) sd.lastAmazonOrderId = amazonOrderId;
sd.lastOrderContext = mergedCtx;

// Determine pose count (prefer explicit meta, then known fields; default 12)
const total =
  Number.isFinite(+j.__meta?.totalPoses)     ? Math.max(1, Math.floor(+j.__meta.totalPoses)) :
  Number.isFinite(+j.totalPosesRequired)     ? Math.max(1, Math.floor(+j.totalPosesRequired)) :
  Number.isFinite(+j.totalPoses)             ? Math.max(1, Math.floor(+j.totalPoses)) :
  Number.isFinite(+j.numPoses)               ? Math.max(1, Math.floor(+j.numPoses)) :
  12;

console.log(`🧩 Expand→${total} poses | using amazonOrderId=${amazonOrderId}`);

const base = {
  ...j,
  amazonOrderId,
  orderContext: mergedCtx,
  assetsRoot : mergedCtx.assetsRoot,
  publicR2Url: mergedCtx.publicR2Url,
};

// Fan-out JSON-only items; no binaries forwarded
const out = [];
for (let n = 1; n <= total; n++) {
  out.push({
    json: {
      ...base,
      poseNumber: n,
      currentPoseNumber: n,
      index: n - 1,
      __meta: { ...(base.__meta || {}), poseNumber: n, totalPoses: total },
    },
    binary: {},            // ensure no binaries carried
    pairedItem: { item: 0 }
  });
}

return out;

// Write Run Manifest (2A-04) — v2.0.3 with GLOBAL ORDER ID SUPPORT
// Single document with manifest + order context + summary + review queue
// Sources results and order context, outputs enriched manifest
// UPDATED: Uses global.currentAmazonOrderId as fallback for cross-context access

console.log('=== Write Run Manifest v2.0.3 with GLOBAL SUPPORT ===');

/* ---------------- helpers ---------------- */
function toInt(v){ const n=Number(v); return Number.isFinite(n)?Math.floor(n):null; }
function nonEmpty(v){ return v!==undefined && v!==null && String(v).trim()!=='' && String(v).toLowerCase()!=='undefined' && String(v).toLowerCase()!=='null'; }
const pickNE = (...vals)=> vals.find(nonEmpty);
const clamp = (n,lo,hi)=> Math.max(lo, Math.min(hi, n));
const HEX_OK = /^[a-f0-9]{12,64}$/i;
const STRICT_RE = /(?:^|\/)characters\/([a-f0-9]{12,64})(?:\/|$)/i;
const LOOSE_RE1 = /characters[_\-]([a-f0-9]{12,64})[_\-]/i;
const LOOSE_RE2 = /characters[_\-]([a-f0-9]{12,64})[_\-]pose\d{1,3}/i;
function extractHashFromString(s){
  if (!nonEmpty(s)) return null;
  const str=String(s);
  let m=str.match(STRICT_RE); if (m) return m[1];
  m=str.match(LOOSE_RE2)||str.match(LOOSE_RE1);
  return m?m[1]:null;
}
function sanitizePath(p){ return String(p||'').replace(/\/{2,}/g,'/').replace(/^\/+/,''); }
function isoNow(){ return new Date().toISOString(); }
function ensureIso(v){ try{ const d=new Date(v); if (!Number.isNaN(d.getTime())) return d.toISOString(); }catch{} return isoNow(); }
function joinUrl(base, key) {
  if (!base || !key) return null;
  return `${String(base).replace(/\/$/, '')}/${String(key).replace(/^\/+/, '')}`;
}

// Scan a node across runs for all items (newest→older)
function itemsAllRuns(nodeName, MAX_SCAN=40){
  const out=[], seen=new Set();
  try{
    const latest = $items(nodeName);
    if (Array.isArray(latest)) for (const it of latest){
      const sig = it?.json?.__uuid || JSON.stringify(Object.keys(it?.binary||{}));
      if (!seen.has(sig)){ seen.add(sig); out.push({ run:'latest', item: it }); }
    }
  }catch{}
  try{
    const last = $items(nodeName,0);
    if (Array.isArray(last)) for (const it of last){
      const sig = it?.json?.__uuid || JSON.stringify(Object.keys(it?.binary||{}));
      if (!seen.has(sig)){ seen.add(sig); out.push({ run:'last', item: it }); }
    }
  }catch{}
  for (let r=MAX_SCAN; r>=0; r--){
    try{
      const arr = $items(nodeName,0,r);
      if (!Array.isArray(arr) || !arr.length) continue;
      for (const it of arr){
        const sig = JSON.stringify([r,it?.json?.__uuid,Object.keys(it?.binary||{})]);
        if (!seen.has(sig)){ seen.add(sig); out.push({ run:r, item: it }); }
      }
    }catch{}
  }
  return out;
}

/* ---------------- gather accumulated results ---------------- */
let accumulatedResults = [];
let runId = null;

/* Strategy 0: DIRECT INPUT */
try{
  const incomingItems = (typeof $input?.all === 'function') ? $input.all() : [];
  const fromItems = incomingItems.map(it => it?.json).filter(Boolean);
  const fromJson  = Array.isArray($json) ? $json : (Object.keys($json||{}).length > 0 ? [$json] : []);
  const combined  = [...fromItems, ...fromJson];
  if (combined.length){
    accumulatedResults = combined;
    runId = pickNE($json?.runId, $json?.runStamp, $execution?.customData?.currentRunId, 'direct');
    console.log(`Strategy 0: direct input provided ${accumulatedResults.length} results`);
  }
}catch(e){
  console.warn('Strategy 0 error:', e?.message || e);
}

/* Strategy 1: currentRunId bucket */
if (accumulatedResults.length === 0 && $execution.customData?.currentRunId){
  runId = $execution.customData.currentRunId;
  accumulatedResults = $execution.customData.poseResults?.[runId] || [];
  console.log(`Strategy 1: currentRunId="${runId}", found ${accumulatedResults.length}`);
}

/* Strategy 2: last bucket in poseResults */
if (accumulatedResults.length === 0 && $execution.customData?.poseResults){
  const allRunIds = Object.keys($execution.customData.poseResults);
  console.log(`Strategy 2: poseResults buckets: ${allRunIds.length}`);
  if (allRunIds.length){
    runId = allRunIds[allRunIds.length-1];
    accumulatedResults = $execution.customData.poseResults[runId] || [];
    console.log(`Strategy 2: picked runId="${runId}", found ${accumulatedResults.length}`);
  }
}

/* Strategy 3: merge all buckets */
if (accumulatedResults.length === 0 && $execution.customData?.poseResults){
  const all = [];
  for (const rid of Object.keys($execution.customData.poseResults)){
    all.push(...($execution.customData.poseResults[rid] || []));
  }
  if (all.length){
    accumulatedResults = all;
    runId = 'merged';
    console.log(`Strategy 3: merged all buckets, found ${accumulatedResults.length}`);
  }
}

/* Strategy 4 (FALLBACK): scan upstream accumulator node outputs across runs */
if (accumulatedResults.length === 0){
  const ACCUM_NODE_NAMES = [
    'Results Accumulator',
    'Accumulator - Collect Pose Results',
    'Accumulator — Collect Pose Results',
    'Accumulator – Collect Pose Results',
    'Collect Pose Results',
    'Pose Results Accumulator',
    'Accumulator - Collect Pose Results (2A)'
  ];
  for (const nm of ACCUM_NODE_NAMES){
    const scan = itemsAllRuns(nm);
    if (scan.length){
      const pulled = scan.map(x => x.item?.json).filter(Boolean);
      if (pulled.length){
        accumulatedResults = pulled;
        runId = runId || 'scanned';
        console.log(`Strategy 4: scanned "${nm}" → ${pulled.length} items`);
        break;
      }
    }
  }
}

console.log(`Final gather → ${accumulatedResults.length} items, runId="${runId||'(none)'}"`);

/* If STILL nothing: emit a soft stub with binary so S3 node doesn't error */
function emitStub(reason){
  const runStamp = isoNow();
  const manifest = {
    schema: 'lhb.run-manifest@v2.0',
    runStamp,
    characterHash: 'unknown',
    order: null,
    poses: {
      total: 0,
      approved: 0,
      exhausted: 0,
      retried: 0,
      failed: 0,
      needingReview: 0
    },
    entries: [],
    reviewQueue: [],
    summary: {
      percentComplete: 0,
      readyForBook: false,
      needsHumanReview: false
    },
    workflow: {
      currentStage: '2A-complete',
      nextWorkflow: 'unknown',
      requiresHumanReview: false
    },
    generatedAt: runStamp,
    _note: `EMPTY MANIFEST: ${reason}`
  };
  const manifestJson = JSON.stringify(manifest, null, 2);

  // Use fallback path structure for stub
