  const qaPoseNotes = result.qa?.pose?.notes || null;
  const qaStyleNotes = result.qa?.style?.notes || null;

  const maxRetries = toInt(pickNE(result.maxPoseRetries, result.maxRetries, 3)) ?? 3;
  const needsReview = result.needsReview === true;
  const reviewReason = result.reviewReason || null;

  const prev = byPose.get(poseNumber) || {
    poseNumber,
    attempts: 0,
    approvedKey: null,
    approvedFilename: null,
    anyPass: false,
    exhausted: false,
    qaScore: null,
    styleScore: null,
    qaReasons: [],
    needsReview: false,
    reviewReason: null,
    maxRetries,
    retryHistory: [],
    publicUrl: null,
    correlationId: null,
    qaPoseNotes: null,
    qaStyleNotes: null
  };

  if (attempt > prev.attempts) prev.attempts = attempt;

  if (!qaPass && qaReasons.length) {
    prev.qaReasons = [...new Set([...prev.qaReasons, ...qaReasons])];
  }

  if (attempt > 0){
    prev.retryHistory.push({
      attempt, passed: qaPass, qaScore, styleScore,
      reasons: qaReasons.length ? qaReasons : null
    });
  }

  prev.anyPass = prev.anyPass || qaPass;

  if (qaPass && approvedKey){
    prev.approvedKey = approvedKey;
    prev.approvedFilename = approvedFilename;
    if (publicUrl) prev.publicUrl = publicUrl;
    if (correlationId) prev.correlationId = correlationId;
  }

  if (qaPoseNotes) prev.qaPoseNotes = qaPoseNotes;
  if (qaStyleNotes) prev.qaStyleNotes = qaStyleNotes;

  if (needsReview){ prev.needsReview = true; prev.reviewReason = reviewReason || prev.reviewReason; }
  if (attempt >= prev.maxRetries) prev.exhausted = true;
