  else if (p.anyPass){ finalStatus='passed_qa'; }

  const isExhausted = p.exhausted && finalStatus !== 'approved';
  if (isExhausted){ finalStatus='exhausted'; exhaustedCount++; }

  // Auto-flag exhausted poses for review
  const needsReview = p.needsReview || isExhausted;
  if (needsReview) needsReviewCount++;

  if (p.attempts >= 1) retriedCount++;

  const entry = {
    poseNumber: p.poseNumber,
    attempts: p.attempts,
    status: finalStatus,
    approved: finalStatus === 'approved',
    approvedKey: p.approvedKey || null,
    approvedFilename: p.approvedFilename || null,
