// CRITICAL FIX: Retrieve FULL orderContext from upstream nodes (not just amazonOrderId)
function findOrderContextFromUpstream(){
  // Priority: Capture Order Context > Generate Character Hash > other nodes
  const CANDIDATES = [
    'Capture Order Context',
    'Generate Character Hash1',
    'Generate Character Hash',
    'Init / Validate Inputs',
    'Set Environment Defaults (code)',
    'Set Environment Defaults',
    'Manual Trigger',
    'Start / Pass-through'
  ];
  for (const name of CANDIDATES){
    try {
      const arr = $items(name);
      if (Array.isArray(arr) && arr.length > 0) {
        const item = arr[0];
        const fullContext = item?.json?.orderContext || item?.json?.orderData || null;
        if (fullContext && (good(fullContext.amazonOrderId) || fullContext.characterSpecs || fullContext.bookSpecs)) {
          console.log(`✓ Found full orderContext from ${name}`);
          return { source: name, context: fullContext };
        }
      }
      const last = $items(name, 0);
      if (Array.isArray(last) && last.length > 0) {
        const item = last[0];
        const fullContext = item?.json?.orderContext || item?.json?.orderData || null;
        if (fullContext && (good(fullContext.amazonOrderId) || fullContext.characterSpecs || fullContext.bookSpecs)) {
          console.log(`✓ Found full orderContext from ${name} (run 0)`);
          return { source: name, context: fullContext };
        }
      }
    } catch (e) {}
  }
  return { source: null, context: null };
}

