// Add a unique signature to avoid scan de-dupe in manifest writer
function makeUuid(r, ix){
  const pose = String(r.poseNumber ?? ix + 1).padStart(2,'0');
  const tail = (r.approvedKey || r.storageKey || r.generatedFileName || '').split('/').pop() || `pose${pose}.png`;
  return `${r.characterHash||'unknown'}:${pose}:${tail}`;
}
if (!result.__uuid) {
  result.__uuid = makeUuid(result, Number(result.poseNumber ?? 0) - 1);
}

// Push into accumulator
if (!$execution.customData.poseResults[runId]) {
  $execution.customData.poseResults[runId] = [];
}
$execution.customData.poseResults[runId].push(result);

// Visibility
try {
  const count = $execution.customData.poseResults[runId].length;
  console.log('ACCUM OK', {
    runId,
    pose: result.poseNumber,
    totalCollected: count,
    amazonOrderId: result.amazonOrderId
  });
} catch {}

return { json: result, binary: {} };
